<script setup lang="ts">
import QRCode from 'qrcode';
import { computed, onBeforeUnmount, ref } from 'vue';
import RouteCanvas from '../components/rust/RouteCanvas.vue';
import SchemaFields from '../components/rust/SchemaFields.vue';
import { authorize, request, events, type Graph, type Layout } from '../api/rust';
import { contracts as fallback } from '../api/rust-contracts.generated';
const token = ref(''), connected = ref(false), busy = ref(false), notice = ref(''), error = ref('');
const tab = ref('routes'), config = ref<any>(), contracts = ref<any>(fallback), status = ref<any>({});
const graph = ref<Graph>(), layout = ref<Layout>({}), drafts = ref<any[]>([]), draftRevision = ref(0), selectedGraph = ref(''), dirty = ref(false);
const traces = ref<any[]>([]), simulation = ref<any>(), sample = ref('/echo CANVAS-OK'), sender = ref('local'), session = ref('local'), platform = ref('cli');
const runList = ref<any[]>([]), runId = ref(''), runEvents = ref<any[]>([]), streamState = ref('未连接');
const resource = ref('agents'), rollbackRevision = ref(1), memoryLibrary = ref(''), knowledgeLibrary = ref('');
const wechatId = ref(''), loginTicket = ref(''), qrImage = ref(''), loginStatus = ref('');
const memoryRows = ref<any[]>([]), documents = ref<any[]>([]), jobs = ref<any[]>([]), query = ref(''), hits = ref<any[]>([]);
let controller: AbortController | undefined;
const schema = computed(() => contracts.value.schemas.application);
const resourceSchema = computed(() => {
  const root = schema.value;
  if (['agents', 'llms', 'ims', 'runtime'].includes(resource.value)) return root.properties[resource.value];
  return root.$defs.ResourceCatalog.properties[resource.value];
});
const resourceValue = computed(() => ['agents', 'llms', 'ims', 'runtime'].includes(resource.value) ? config.value?.[resource.value] : config.value?.resources?.[resource.value]);
function setResource(value: any) { if (['agents', 'llms', 'ims', 'runtime'].includes(resource.value)) config.value[resource.value] = value; else config.value.resources[resource.value] = value; dirty.value = true; }
async function action(fn: () => Promise<void>) { busy.value = true; error.value = ''; notice.value = ''; try { await fn(); } catch (e) { error.value = String(e); } finally { busy.value = false; } }
async function refresh() { const [c, s, d] = await Promise.all([request('config'), request('status'), request<any[]>('drafts')]); config.value = c; status.value = s; drafts.value = d; dirty.value = false; }
async function login() { await action(async () => { authorize(token.value); contracts.value = await request('contracts'); await refresh(); connected.value = true; token.value = ''; platform.value = config.value.ims[0]?.id || 'cli'; choose(config.value.graphs[0]?.id); controller?.abort(); controller = new AbortController(); streamState.value = '已连接'; void events(controller.signal, value => { if (value.type === 'gap') { streamState.value = '存在缺口，请刷新执行记录'; return; } if (value.run_id === runId.value) { runEvents.value.push(value); if (runEvents.value.length > 500) runEvents.value.shift(); if (value.event?.node_id) traces.value.push(value.event); } }).catch(e => { if (e.name !== 'AbortError') streamState.value = '连接中断，可重新连接'; }); }); }
function logout() { controller?.abort(); authorize(''); connected.value = false; config.value = undefined; }
function choose(id?: string) { if (!id) return; const g = config.value.graphs.find((g: Graph) => g.id === id); if (!g) return; selectedGraph.value = id; graph.value = JSON.parse(JSON.stringify(g)); const d = drafts.value.find(d => d.id === id); layout.value = d?.body?.layout || {}; draftRevision.value = d?.revision || 0; traces.value = []; simulation.value = undefined; }
function newGraph() { const id = `route_${crypto.randomUUID().slice(0, 8)}`; graph.value = { schema_version: 1, id, revision: 1, entry: 'input', nodes: [{ id: 'input', type: 'input' }, { id: 'agent', type: 'agent', agent_id: config.value.agents[0]?.definition.id || '' }, { id: 'reply', type: 'reply', content: null }, { id: 'end', type: 'end', reason: 'complete' }], edges: [{ from: 'input', port: 'next', to: 'agent' }, { from: 'agent', port: 'next', to: 'reply' }, { from: 'reply', port: 'next', to: 'end' }] }; selectedGraph.value = ''; layout.value = {}; draftRevision.value = 0; dirty.value = true; }
function loadDraft() { const draft = drafts.value.find(d => d.id === graph.value?.id); if (!draft) return; graph.value = JSON.parse(JSON.stringify(draft.body.graph)); layout.value = draft.body.layout || {}; draftRevision.value = draft.revision; dirty.value = true; }
async function save() { await action(async () => { if (!graph.value) return; const r = await request(`drafts/${encodeURIComponent(graph.value.id)}`, { expected_revision: draftRevision.value, body: { graph: graph.value, layout: layout.value } }, 'PUT'); draftRevision.value = r.revision; drafts.value = await request('drafts'); dirty.value = false; notice.value = '草稿已保存，线上路由未变更。'; }); }
async function validate() { await action(async () => { await request('graphs/validate', graph.value); notice.value = '路由校验通过'; }); }
async function publish() { await action(async () => { if (!graph.value) return; await request('graphs/validate', graph.value); const g = JSON.parse(JSON.stringify(graph.value)); const old = config.value.graphs.find((v: Graph) => v.id === g.id); g.revision = old ? old.revision + 1 : 1; await request('graphs/publish', { expected_revision: config.value.revision, graph: g }); await refresh(); choose(g.id); notice.value = '路由已发布。新路由需在 IM 配置中绑定。'; }); }
async function simulate() { await action(async () => { simulation.value = await request('graphs/simulate-draft', { graph: graph.value, event: { identity: { platform: platform.value, session: session.value, sender: sender.value, message_id: 'simulation' }, input: sample.value } }); traces.value = simulation.value.run.traces; }); }
async function publishConfig() { await action(async () => { const c = JSON.parse(JSON.stringify(config.value)); c.revision++; await request('config', { expected_revision: config.value.revision, config: c }, 'PUT'); await refresh(); notice.value = '配置已发布。IM 连接及全局并发预算变更需重启服务。'; }); }
async function rollback() { await action(async () => { await request('config/rollback', { expected_revision: config.value.revision, target_revision: rollbackRevision.value }); await refresh(); choose(graph.value?.id); notice.value = '已以新修订恢复指定配置'; }); }
async function listRuns() { await action(async () => { runList.value = await request('runs'); }); }
async function inspectRun(id: string) { await action(async () => { runId.value = id; runEvents.value = await request(`runs/${encodeURIComponent(id)}/events`); traces.value = runEvents.value.map(e => e.event).filter(e => e.node_id); }); }
async function listMemory() { if (!memoryLibrary.value) return; memoryRows.value = await request(`memory/${encodeURIComponent(memoryLibrary.value)}`); }
async function forget(id: string) { await action(async () => { await request(`memory/${encodeURIComponent(memoryLibrary.value)}/${encodeURIComponent(id)}`, undefined, 'DELETE'); await listMemory(); }); }
async function listKnowledge() { if (!knowledgeLibrary.value) return; const l = encodeURIComponent(knowledgeLibrary.value); [documents.value, jobs.value] = await Promise.all([request<any[]>(`knowledge/${l}`), request<any[]>(`knowledge/${l}/jobs`)]); }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await action(async () => { if (file.size > 10 * 1024 * 1024) throw new Error('文件超过 10 MiB'); const encoded = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file); }); await request(`knowledge/${encodeURIComponent(knowledgeLibrary.value)}/import`, { document_id: crypto.randomUUID(), name: file.name, base64: encoded }); await listKnowledge(); }); }
async function knowledgeAction(id: string, mode: 'rebuild' | 'delete') { await action(async () => { await request(`knowledge/${encodeURIComponent(knowledgeLibrary.value)}/${encodeURIComponent(id)}${mode === 'rebuild' ? '/rebuild' : ''}`, mode === 'rebuild' ? {} : undefined, mode === 'delete' ? 'DELETE' : 'POST'); await listKnowledge(); }); }
async function search() { await action(async () => { hits.value = await request(`knowledge/${encodeURIComponent(knowledgeLibrary.value)}/search?query=${encodeURIComponent(query.value)}`); }); }
async function startWechat() { await action(async () => { const result = await request(`ims/${encodeURIComponent(wechatId.value)}/login/start`, {}); loginTicket.value = result.qrcode; qrImage.value = await QRCode.toDataURL(result.content, { width: 280, margin: 2 }); loginStatus.value = '请用微信扫描二维码；有效期约五分钟'; }); }
async function pollWechat() { await action(async () => { const result = await request(`ims/${encodeURIComponent(wechatId.value)}/login/poll`, { qrcode: loginTicket.value }); loginStatus.value = result.status === 'confirmed' ? '登录成功，账号已私密保存；重启服务后接入。' : result.status === 'expired' ? '二维码已过期，请重新生成。' : result.status; if (result.status === 'confirmed') { loginTicket.value = ''; qrImage.value = ''; } }); }
onBeforeUnmount(() => controller?.abort());
</script>
<template>
<section class="rust-runtime">
  <header class="page-heading"><div><h1>Rust 运行中心</h1><p>Agent、路由与资源的统一配置</p></div><span v-if="connected">修订 {{ config.revision }} · {{ dirty ? '有未保存修改' : '已同步' }}</span><button v-if="connected" @click="logout">退出</button></header>
  <form v-if="!connected" class="login" @submit.prevent="login"><h2>连接管理服务</h2><p>令牌只保存在当前页面内存中。</p><label>管理令牌<input v-model="token" type="password" autocomplete="off" required minlength="32"></label><button :disabled="busy">连接</button></form>
  <p v-if="error" role="alert" class="error">{{ error }}<span v-if="error.includes('409')"> · 服务端版本已变化；请先保存本地草稿，再重新载入并合并。</span></p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
  <template v-if="connected"><nav><button v-for="[id, name] in [['routes', '可视化路由'], ['resources', 'Agent 与资源'], ['knowledge', '记忆与知识库'], ['runs', '执行记录'], ['status', '运行状态']]" :key="id" :class="{ active: tab === id }" @click="tab = id">{{ name }}</button></nav>
  <section v-if="tab === 'routes'" class="panel"><div class="toolbar"><label>路由<select :value="selectedGraph" @change="choose(($event.target as HTMLSelectElement).value)"><option v-for="g in config.graphs" :key="g.id" :value="g.id">{{ g.id }} · r{{ g.revision }}</option></select></label><button @click="newGraph">新建</button><button :disabled="busy || !graph" @click="loadDraft">载入草稿</button><button :disabled="busy || !graph" @click="save">保存草稿</button><button :disabled="busy || !graph" @click="validate">校验</button><button class="primary" :disabled="busy || !graph" @click="publish">发布路由</button></div>
  <template v-if="graph"><RouteCanvas :graph="graph" :layout="layout" :catalog="contracts.nodes" :states="contracts.runtime_states" :agents="config.agents.map((a: any) => a.definition.id)" :traces="traces" @change="(g, l) => { graph = g; layout = l; dirty = true; }" /><details><summary>图级权限与运行预算</summary><SchemaFields :model-value="graph.permissions || { resources: [] }" :schema="schema.$defs.PermissionLimits" :root="schema" label="权限上限" @update:model-value="graph.permissions = $event; dirty = true" /><SchemaFields :model-value="graph.limits" :schema="schema.$defs.GraphLimits" :root="schema" label="执行预算" @update:model-value="graph.limits = $event; dirty = true" /></details>
  <form class="simulation" @submit.prevent="simulate"><h3>模拟消息</h3><label>IM 实例<input v-model="platform"></label><label>会话<input v-model="session"></label><label>调用者<input v-model="sender"></label><label class="wide">消息<input v-model="sample"></label><button :disabled="busy">模拟草稿（不产生副作用）</button></form><div v-if="simulation" class="result"><strong>运行态：{{ simulation.run.state }} · Agent：{{ simulation.run.selected_agent || '无' }} · {{ simulation.run.reason }}</strong><p>{{ simulation.run.traces.map((t: any) => `${t.node_id} [${t.port}]`).join(' → ') }}</p><p v-if="simulation.run.error" class="error">{{ simulation.run.error }}</p></div></template></section>
  <section v-if="tab === 'resources'" class="panel"><div class="toolbar"><select v-model="resource" aria-label="资源类型"><option v-for="[id, label] in [['agents', 'Agent'], ['llms', '模型连接'], ['ims', 'IM 连接与路由绑定'], ['personas', '人格'], ['environments', '执行环境'], ['skills', 'Skills'], ['mcp', 'MCP'], ['memories', '记忆库'], ['knowledge', '知识库'], ['runtime', '运行预算']]" :key="id" :value="id">{{ label }}</option></select><button class="primary" :disabled="busy" @click="publishConfig">发布配置</button><button :disabled="busy" @click="action(refresh)">重新载入</button></div><SchemaFields :model-value="resourceValue" :schema="resourceSchema" :root="schema" :label="resource" @update:model-value="setResource" /><details><summary>工具目录</summary><div v-for="tool in contracts.tools" :key="tool.name"><strong>{{ tool.name }}</strong> · {{ tool.minimum_state }}<p>{{ tool.description }}</p></div></details><div class="toolbar"><label>恢复修订<input v-model.number="rollbackRevision" type="number" min="1"></label><button :disabled="busy" @click="rollback">恢复为新修订</button></div></section>
  <section v-if="tab === 'knowledge'" class="panel"><h2>长期记忆</h2><div class="toolbar"><select v-model="memoryLibrary" aria-label="记忆库" @change="action(listMemory)"><option value="">选择记忆库</option><option v-for="m in config.resources.memories" :key="m.id" :value="m.id">{{ m.name || m.id }}</option></select><button :disabled="busy" @click="action(listMemory)">刷新</button></div><table><thead><tr><th>内容</th><th>作用域</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="row in memoryRows" :key="row.id"><td>{{ row.content }}</td><td>{{ row.scope }} · {{ row.platform }} / {{ row.session }} / {{ row.sender }}</td><td>{{ row.source }} · {{ row.confidence }}</td><td><button :disabled="busy" @click="forget(row.id)">删除并禁止自动恢复</button></td></tr></tbody></table><h2>知识库</h2><div class="toolbar"><select v-model="knowledgeLibrary" aria-label="知识库" @change="action(listKnowledge)"><option value="">选择知识库</option><option v-for="k in config.resources.knowledge" :key="k.id" :value="k.id">{{ k.name || k.id }}</option></select><button :disabled="busy" @click="action(listKnowledge)">刷新任务</button><label v-if="knowledgeLibrary">导入文本或 PDF<input type="file" accept=".txt,.md,.pdf" :disabled="busy" @change="upload"></label></div><table><thead><tr><th>文档</th><th>生效版本</th><th>操作</th></tr></thead><tbody><tr v-for="doc in documents" :key="doc.id"><td>{{ doc.name }}</td><td>{{ doc.version || '未生效' }}</td><td><button :disabled="busy" @click="knowledgeAction(doc.id, 'rebuild')">重新索引</button><button :disabled="busy" @click="knowledgeAction(doc.id, 'delete')">删除</button></td></tr></tbody></table><ul><li v-for="job in jobs" :key="job.id">{{ job.document_id }} v{{ job.version }} · {{ job.status }} {{ job.error }} <button v-if="job.status === 'running'" @click="action(async () => { await request(`knowledge-jobs/${job.id}/cancel`, {}); await listKnowledge(); })">取消</button></li></ul><form v-if="knowledgeLibrary" class="toolbar" @submit.prevent="search"><input v-model="query" aria-label="检索问题" placeholder="输入检索问题"><button :disabled="busy">检索</button></form><article v-for="hit in hits" :key="hit.citation"><strong>{{ hit.citation }}</strong><p>{{ hit.text }}</p></article></section>
  <section v-if="tab === 'runs'" class="panel"><div class="toolbar"><button :disabled="busy" @click="listRuns">刷新执行记录</button><span>实时事件：{{ streamState }}</span></div><table><thead><tr><th>运行</th><th>父运行</th><th>Agent / 状态</th><th>结果</th></tr></thead><tbody><tr v-for="run in runList" :key="run.id"><td><button @click="inspectRun(run.id)">{{ run.id.slice(0, 8) }}</button></td><td><button v-if="run.parent_id" @click="inspectRun(run.parent_id)">{{ run.parent_id.slice(0, 8) }}</button></td><td>{{ run.agent_id }} / {{ run.state }}</td><td>{{ run.status }}</td></tr></tbody></table><h3 v-if="runId">{{ runId }}</h3><ol class="event-list"><li v-for="(entry, i) in runEvents" :key="`${entry.sequence}-${i}`"><strong>{{ entry.event?.type }}</strong><pre>{{ JSON.stringify(entry.event, null, 2) }}</pre></li></ol></section>
  <section v-if="tab === 'status'" class="panel"><button :disabled="busy" @click="action(async () => { status = await request('status'); })">刷新状态</button><h2>引擎与并发</h2><pre>{{ JSON.stringify({ engine: status.engine, sessions: status.sessions }, null, 2) }}</pre><h2>微信 iLink 登录</h2><div class="toolbar"><select v-model="wechatId" aria-label="微信实例"><option value="">选择已配置微信实例</option><option v-for="im in config.ims.filter((im: any) => im.connection?.type === 'wechat')" :key="im.id" :value="im.id">{{ im.id }}</option></select><button :disabled="busy || !wechatId" @click="startWechat">生成登录二维码</button><button :disabled="busy || !loginTicket" @click="pollWechat">检查扫码状态</button></div><img v-if="qrImage" :src="qrImage" alt="微信登录二维码" width="280" height="280"><p role="status">{{ loginStatus }}</p><h2>平台连接</h2><pre>{{ JSON.stringify(status.platform_health, null, 2) }}</pre><h2>执行环境能力</h2><pre>{{ JSON.stringify(status.environments, null, 2) }}</pre></section>
  </template>
</section>
</template>
<style scoped>
.rust-runtime{color:var(--text-primary,#0f172a);max-width:1800px;margin:auto}.page-heading,.toolbar,nav{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.page-heading{justify-content:space-between;margin-bottom:24px}.page-heading h1{margin:0}.page-heading p{color:#64748b}nav{border-bottom:1px solid #cbd5e1;margin-bottom:20px;padding-bottom:12px}button,input,select,textarea{font:inherit}button{background:#fff;color:#334155;border:1px solid #94a3b8;border-radius:6px;padding:8px 12px;cursor:pointer}button:hover{background:#eff6ff}button:disabled{opacity:.5;cursor:default}button.active,button.primary{background:#1d4ed8;color:white;border-color:#1d4ed8}input,select{border:1px solid #94a3b8;border-radius:6px;padding:8px;color:#0f172a;background:#fff}label{display:grid;gap:5px}.panel{background:var(--surface,#fff);padding:16px;border:1px solid #cbd5e1;border-radius:12px}.toolbar{margin-bottom:16px}.login{max-width:430px;margin:60px auto;padding:30px;border:1px solid #cbd5e1;border-radius:12px}.login button{margin-top:15px}.error{color:#b91c1c;background:#fef2f2;padding:12px;border-radius:6px}.notice,.result{color:#065f46;background:#ecfdf5;padding:12px;border-radius:6px}.simulation{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:16px 0}.simulation h3,.wide{grid-column:1/-1}.simulation button{grid-column:1/-1;justify-self:start}.result{margin-top:12px}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{text-align:left;padding:10px;border-bottom:1px solid #cbd5e1;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:500px;overflow:auto}.event-list li{padding:12px;border-left:2px solid #2563eb;margin-bottom:12px}details{margin:16px 0}summary{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #60a5fa;outline-offset:2px}@media(max-width:800px){.simulation{grid-template-columns:1fr}.panel{padding:8px}}
</style>
